function HomelandCheckInAttributeNode:Refresh(data, index)
    if isNull(data) then
        return
    end
    self.data = data
    local typeId = data.typeId
    local voId = data.voId
    local canActiveIndex = data.canActiveIndex
    local vo = self.comp:GetBonusVo(voId)
    if isNull(vo) then
        return
    end

    KTool.SetActive(self.ImgBg, index % 2 == 1)

    -- 这一条是否激活
    local active = index == canActiveIndex
    
    -- 数量
    CfUtils.FillText(self.TxtNumber, vo.num)
    CfUtils.SetUISwitchText(self.TxtNumber, active and 2 or 1)
    
    -- 描述
    local showNum = num_floor(vo.attrNums[1] * 100)
    local desc = localize("小队基础属性x_num_%", {_num_ = showNum})
    CfUtils.FillText(self.TxtName, desc)
    CfUtils.SetUISwitchText(self.TxtName, active and 2 or 1)
end

